let preview=null;let manualItems=[];let liveTimer=null;
function me(){return store.data.users.find(u=>u.id===store.data.session.userId);}
function isManager(){return ['ADMIN_GLOBAL','ADMINISTRADOR','ENCARGADO'].includes(me()?.role);}
function isGlobalManager(){const u=me();return u?.role==='ADMIN_GLOBAL'||(u?.role==='ADMINISTRADOR'&&!(u.siteIds||[]).length);}
function operators(){return (store.data.users||[]).filter(u=>u.active!==false&&['OPERADOR_BODEGA','OPERADOR_RECEPCION','ENCARGADO'].includes(u.role)&&(!(u.siteIds||[]).length||(u.siteIds||[]).some(id=>store.data.sites.find(s=>s.id===id)?.companyId===activeCompanyId())));}
function statusLabel(s){return ({RECIBIDA:'Recibida',ACEPTADA:'Aceptada',ASIGNADA:'Asignada',EN_PICKING:'En picking',PREPARADA:'Preparada',PENDIENTE_EMISION:'Picking culminado · pendiente de emisión',EMITIDA:'Emitida y cerrada',ENTREGADA_CONDUCTOR:'Entregada al conductor',CERRADA:'Cerrada'}[s]||s);}
function statusTone(s){return s==='CERRADA'||s==='EMITIDA'||s==='ENTREGADA_CONDUCTOR'?'ok':s==='EN_PICKING'||s==='PENDIENTE_EMISION'?'warn':'neutral';}
function progress(o){const total=(o.items||[]).length,done=(o.items||[]).filter(i=>Number(i.pickedQty||0)>=Number(i.qty||0)).length;return {total,done,pct:total?Math.round(done*100/total):0};}
function siteName(id){return store.data.sites.find(s=>s.id===id)?.name||id||'—';}
function destinationName(o){return o.requestSiteId?siteName(o.requestSiteId):(o.recipient?.name||o.destinationName||'Destinatario externo');}
function orderTypeLabel(type){return ({PEDIDO_CLIENTE:'Pedido de cliente',TRASPASO_INTERNO:'Traspaso interno',FACTURA_DIRECTA:'Factura directa',ORDEN_INTERNA:'Orden interna',GUIA_DESPACHO:'Guía de despacho',OTRO:'Otro'}[type]||type||'Pedido de cliente');}
function savedRecipients(){return (store.data.settings?.orderRecipients||[]).filter(r=>r.active!==false&&(!r.companyId||r.companyId===activeCompanyId())).sort((a,b)=>String(a.name||'').localeCompare(String(b.name||''),'es'));}
function aliasChips(product){return productAliases(product).map(code=>`<span>${esc(code)}</span>`).join('');}
function productSuggestions(raw){const q=String(raw||'').trim().toLowerCase();if(!q)return [];const exact=resolveProduct(raw);if(exact)return [exact];const tokens=q.split(/\s+/).filter(Boolean);return (store.data.products||[]).filter(p=>{const hay=`${p.code} ${p.name||''} ${p.description||''} ${productAliases(p).join(' ')}`.toLowerCase();return tokens.every(t=>hay.includes(t));}).slice(0,8);}
function userName(id){return store.data.users.find(u=>u.id===id)?.name||'Sin asignar';}
function visibleOrders(){const u=me(),company=activeCompanyId(),allowed=new Set((u?.siteIds||[]).length?u.siteIds:[store.data.session?.activeSiteId||localStorage.getItem('serco_wms_active_site')||'REC']);const sameCompany=o=>siteCompanyId(store.data.sites.find(s=>s.id===o.sourceSiteId))===company;if(isManager())return (store.data.orders||[]).filter(o=>sameCompany(o)&&(isGlobalManager()||allowed.has(o.sourceSiteId)));return (store.data.orders||[]).filter(o=>o.assignedTo===u?.id&&sameCompany(o));}
function defaultDocumentType(o){return ({FACTURA_DIRECTA:'FACTURA',TRASPASO_INTERNO:'TRASPASO',GUIA_DESPACHO:'GUIA_DESPACHO',PEDIDO_CLIENTE:'PEDIDO',ORDEN_INTERNA:'OTRO',OTRO:'OTRO'}[o.orderType]||'PEDIDO');}
function orderSearchText(o){const products=(o.items||[]).flatMap(it=>{const p=store.data.products.find(x=>x.code===it.productCode);return [it.productCode,p?.name,p?.description,...productAliases(p)];});const people=[userName(o.assignedTo),userName(o.createdBy),userName(o.pickingCompletedBy),userName(o.closedBy)];const recipient=o.recipient||{};return [o.id,o.externalNumber,o.finalDocumentNumber,o.finalDocumentType,orderTypeLabel(o.orderType),statusLabel(o.status),siteName(o.sourceSiteId),destinationName(o),recipient.name,recipient.taxId,recipient.address,recipient.contact,o.finalReceiver,o.finalNotes,...people,...products,o.createdAt,o.closedAt,o.createdAt&&new Date(o.createdAt).toLocaleDateString('es-CL'),o.closedAt&&new Date(o.closedAt).toLocaleDateString('es-CL')].filter(Boolean).join(' ').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();}
function locationRows(code,siteId){return (store.data.inventory||[]).filter(i=>i.productCode===code&&Number(i.qty)>0).filter(i=>{const l=store.data.locations.find(x=>x.id===i.locationId);return (l?.siteId||'REC')===siteId;});}
function locationText(code,siteId){const rows=locationRows(code,siteId);return rows.map(i=>{const loc=store.data.locations.find(x=>x.id===i.locationId);return `${i.palletId||vistaCodigoUbicacion(loc,store.data)||i.locationId} · ${Number(i.qty)} un.`;}).join(' · ')||'Sin stock localizado en este centro';}
function normalizedSearch(v=''){return String(v).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().trim();}
function itemSearchText(it){const p=store.data.products.find(x=>x.code===it.productCode);return normalizedSearch(`${it.productCode} ${p?.name||''} ${p?.description||''} ${productAliases(p).join(' ')}`);}
function orderItemMatches(o,raw){const q=normalizedSearch(raw);if(!q)return [];const tokens=q.split(/\s+/).filter(Boolean);return (o.items||[]).filter(it=>{const hay=itemSearchText(it);return tokens.every(t=>hay.includes(t));});}
function resolveOrderProduct(o,raw){const q=normalizedSearch(raw).replace(/[^a-z0-9]/g,''),matches=(o.items||[]).map(it=>store.data.products.find(p=>p.code===it.productCode)).filter(Boolean).filter(p=>[p.code,...productAliases(p)].some(code=>normalizedSearch(code).replace(/[^a-z0-9]/g,'')===q));return matches.find(p=>normalizedSearch(p.code).replace(/[^a-z0-9]/g,'')===q)||matches[0]||resolveProduct(raw);}
function locationCardsHtml(code,siteId){const rows=locationRows(code,siteId);if(!rows.length)return '<div class="pick-focus-no-location">Sin stock localizado en este centro</div>';return rows.map(i=>{const loc=store.data.locations.find(x=>x.id===i.locationId),label=i.palletId||vistaCodigoUbicacion(loc,store.data)||i.locationId;return `<div class="pick-focus-location"><span>UBICACIÓN</span><b>${esc(label)}</b><strong>${Number(i.qty)} un.</strong></div>`;}).join('');}
function pickFocusHtml(o,raw){const matches=orderItemMatches(o,raw);if(!raw.trim())return '';if(!matches.length)return `<div class="pick-focus-empty"><b>No pertenece a esta orden</b><span>La búsqueda global puede mostrar el producto, pero no está solicitado en esta tarea.</span></div>`;return matches.map(it=>{const p=store.data.products.find(x=>x.code===it.productCode),requested=Number(it.qty||0),picked=Number(it.pickedQty||0),pending=Math.max(0,requested-picked);return `<article class="pick-focus-card"><div class="pick-focus-product"><span>PRODUCTO ENCONTRADO</span><h3>${esc(it.productCode)} · ${esc(p?.name||p?.description||'Producto')}</h3><small>Códigos: ${esc(productAliases(p).join(' - '))}</small></div><div class="pick-focus-quantity"><span>SOLICITADO</span><strong>${requested}</strong><small>Preparado ${picked} · Pendiente ${pending}</small></div><div class="pick-focus-locations">${locationCardsHtml(it.productCode,o.sourceSiteId)}</div><a class="secondary" href="#/mapa3d?code=${encodeURIComponent(it.productCode)}&returnOrder=${encodeURIComponent(o.id)}">Ver en mapa 3D</a></article>`;}).join('');}
function pickSuggestionsHtml(o,raw){const matches=productSuggestions(raw);if(!raw.trim())return '';if(!matches.length)return '<div class="pick-suggestion-empty">Sin coincidencias globales por código, nombre o descripción.</div>';return matches.map(p=>{const inOrder=(o.items||[]).some(i=>i.productCode===p.code),stock=stockStatus(p.code,o.sourceSiteId,store.data,o.id);return `<div class="pick-suggestion ${inOrder?'in-order':'outside-order'}"><button type="button" class="pick-suggestion-select" data-code="${esc(p.code)}"><span><b>${esc(p.code)} · ${esc(p.name||p.description||'Producto')}</b><small>${inOrder?'Incluido en esta orden':'No pertenece a esta orden'} · ${esc(locationText(p.code,o.sourceSiteId))}</small></span><strong>${stock.physical} un.<small>${stock.available} disponibles</small></strong></button><a href="#/mapa3d?code=${encodeURIComponent(p.code)}&returnOrder=${encodeURIComponent(o.id)}">Mapa 3D</a></div>`;}).join('');}
function printableDocument(o){const company=store.data.companies?.find(c=>c.id===activeCompanyId());const recipient=o.recipient||{};const lines=(o.items||[]).map((it,n)=>{const p=store.data.products.find(x=>x.code===it.productCode),requested=Number(it.qty||0),prepared=Number(it.dispatchedQty??it.pickedQty??0);return `<tr><td>${n+1}</td><td><b>${esc(it.productCode)}</b><br><small>${esc(productAliases(p).join(' - '))}</small></td><td>${esc(p?.name||p?.description||'Producto')}</td><td>${requested}</td><td>${prepared}</td><td>${Math.max(0,requested-prepared)}</td></tr>`;}).join('');return `<!doctype html><html lang="es"><head><meta charset="utf-8"><title>${esc(o.finalDocumentType||'Documento')} ${esc(o.finalDocumentNumber||o.externalNumber)}</title><style>@page{size:A4;margin:14mm}*{box-sizing:border-box}body{font-family:Arial,sans-serif;color:#0f172a;margin:0;font-size:12px}header{display:flex;justify-content:space-between;border-bottom:3px solid #16a34a;padding-bottom:12px;margin-bottom:18px}h1{margin:0;font-size:23px}h2{margin:3px 0;font-size:18px;color:#15803d}.meta{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-bottom:18px}.box{border:1px solid #cbd5e1;border-radius:8px;padding:10px}.box b,.box span{display:block}.box span{margin-top:3px}table{width:100%;border-collapse:collapse}th{background:#f1f5f9;text-align:left}th,td{padding:8px;border:1px solid #cbd5e1;vertical-align:top}small{color:#64748b}.foot{margin-top:20px;border-top:1px solid #cbd5e1;padding-top:10px}.actions{position:fixed;right:14px;top:14px}@media print{.actions{display:none}}</style></head><body><button class="actions" onclick="window.print()">Imprimir / Guardar PDF</button><header><div><h1>${esc(company?.name||'WMS')}</h1><span>Documento operativo emitido por WMS</span></div><div><h2>${esc(o.finalDocumentType||'DOCUMENTO')} ${esc(o.finalDocumentNumber||o.externalNumber)}</h2><span>Orden origen: ${esc(o.externalNumber||o.id)}</span></div></header><section class="meta"><div class="box"><b>Origen</b><span>${esc(siteName(o.sourceSiteId))}</span><b>Destino / recibido por</b><span>${esc(o.finalReceiver||destinationName(o))}</span></div><div class="box"><b>Fecha de emisión</b><span>${o.closedAt?new Date(o.closedAt).toLocaleString('es-CL'):'—'}</span><b>Operador / emisor</b><span>${esc(userName(o.assignedTo))} / ${esc(userName(o.closedBy))}</span></div><div class="box"><b>Destinatario registrado</b><span>${esc(recipient.name||destinationName(o))}</span><span>${esc(recipient.taxId||'Sin identificación')} · ${esc(recipient.contact||'Sin contacto')}</span><span>${esc(recipient.address||'Sin dirección registrada')}</span></div><div class="box"><b>Tipo de orden original</b><span>${esc(orderTypeLabel(o.orderType))}</span><b>Observación</b><span>${esc(o.finalNotes||'Sin observaciones')}</span></div></section><table><thead><tr><th>#</th><th>Código / asociados</th><th>Producto</th><th>Solicitado</th><th>Emitido</th><th>Faltante</th></tr></thead><tbody>${lines}</tbody></table><div class="foot">Documento generado desde la orden WMS ${esc(o.id)}. El stock fue descontado al emitir y cerrar.</div><script>window.addEventListener('load',()=>setTimeout(()=>window.print(),250))<\/script></body></html>`;}
function showPrintableDocument(o){let dlg=document.querySelector('#issued-document-preview');if(!dlg){document.body.insertAdjacentHTML('beforeend',`<dialog id="issued-document-preview" class="issued-document-preview"><div class="issued-preview-card"><div class="dialog-head"><div><span class="eyebrow">VISTA PREVIA</span><h3>Documento emitido</h3></div><button id="close-issued-preview" class="ghost" type="button">×</button></div><iframe id="issued-preview-frame" title="Vista previa del documento"></iframe><div class="dialog-actions"><button id="cancel-issued-preview" class="ghost" type="button">Cerrar</button><button id="print-issued-preview" class="primary" type="button">Imprimir / guardar PDF</button></div></div></dialog>`);dlg=document.querySelector('#issued-document-preview');}const frame=dlg.querySelector('#issued-preview-frame');frame.srcdoc=printableDocument(o).replace(/<script>[\s\S]*?<\/script>/i,'');const close=()=>dlg.close();dlg.querySelector('#close-issued-preview').onclick=close;dlg.querySelector('#cancel-issued-preview').onclick=close;dlg.querySelector('#print-issued-preview').onclick=()=>frame.contentWindow?.print();dlg.showModal();}

function itemAvailability(o,it){
 const origin=stockStatus(it.productCode,o.sourceSiteId,store.data,o.id),requested=Number(it.qty||0),shortage=Math.max(0,requested-origin.available);
 const others=(store.data.sites||[]).filter(s=>s.id!==o.sourceSiteId&&siteCompanyId(s)===siteCompanyId(store.data.sites.find(x=>x.id===o.sourceSiteId))&&s.active!==false).map(s=>({site:s,...stockStatus(it.productCode,s.id,store.data)})).filter(x=>x.available>0).sort((a,b)=>b.available-a.available);
 return {origin,requested,shortage,others};
}
function availabilityHtml(o){
 const blocks=(o.items||[]).map(it=>{const a=itemAvailability(o,it),p=store.data.products.find(x=>x.code===it.productCode);return `<div class="availability-row"><div><b>${esc(it.productCode)} · ${esc(p?.name||'Producto')}</b><small>Solicitado ${a.requested} · Físico ${a.origin.physical} · Reservado por otros ${a.origin.reserved} · Disponible ${a.origin.available}</small></div><div>${a.shortage?badge(`Faltan ${a.shortage}`,'warn'):badge('Disponible','ok')}</div>${a.shortage?(a.others.length?`<div class="availability-transfer"><select class="shortage-site" data-code="${esc(it.productCode)}"><option value="">Elegir centro con stock…</option>${a.others.map(x=>`<option value="${esc(x.site.id)}">${esc(x.site.name)} · ${x.available} disponibles</option>`).join('')}</select><button class="secondary request-shortage" data-code="${esc(it.productCode)}" data-qty="${a.shortage}" type="button">Solicitar traspaso</button></div>`:`<div class="availability-no-source"><b>Sin stock en otros centros</b><small>Puede emitirse parcial o dejarse esperando reposición.</small></div>`):''}</div>`;}).join('');
 return `<details class="order-availability order-collapsible"><summary><span><b>Stock y disponibilidad</b><small>Físico, reservado, disponible y alternativas en otras sucursales.</small></span><strong>Mostrar</strong></summary><div class="order-collapsible-content">${blocks}</div></details>`;
}
function ensureReceivingLocation(state,siteId){let loc=(state.locations||[]).find(l=>l.siteId===siteId&&l.kind==='RECEPCION_TRANSFERENCIA');if(!loc){loc={id:`${siteId}-RECEPCION-TRF`,siteId,rackId:null,module:null,level:null,label:`Recepción temporal ${siteId}`,scanCode:`${siteId}-RECEPCION-TRF`,status:'LIBRE',access:'DIRECTO',kind:'RECEPCION_TRANSFERENCIA',active:true,capacity:null,notes:'Zona temporal para traspasos internos recibidos.'};state.locations.push(loc);}return loc;}
async function requestShortage(o,code,qty,sourceSiteId){if(!sourceSiteId){toast('Selecciona la sucursal de origen','warning');return;}const available=stockStatus(code,sourceSiteId,store.data).available;if(available<1){toast('Ese centro ya no tiene stock disponible','warning');return;}const amount=Math.min(Number(qty||0),available);const id=`TRF-${Date.now()}`;await store.commit(s=>{s.transfers=s.transfers||[];s.transfers.unshift({id,type:'REPOSICION_PEDIDO',orderId:o.id,sourceSiteId,destinationSiteId:o.sourceSiteId,status:'SOLICITADA',createdAt:new Date().toISOString(),createdBy:s.session.userId,items:[{code,qty:amount}],destinationName:siteName(o.sourceSiteId)});const x=s.orders.find(q=>q.id===o.id);x.status=x.status==='PREPARADA'?'PREPARADA':'ESPERANDO_REPOSICION';x.events=x.events||[];x.events.push({at:new Date().toISOString(),userId:s.session.userId,message:`Solicitado traspaso de ${amount} un. de ${code} desde ${siteName(sourceSiteId)}`});},`Traspaso ${id} solicitado para orden ${o.externalNumber||o.id}`);toast('Traspaso solicitado');}
async function advanceTransfer(t){if(t.status==='SOLICITADA'){await store.commit(s=>{const x=s.transfers.find(z=>z.id===t.id);x.status='EN_TRANSITO';x.departedAt=new Date().toISOString();x.dispatchedBy=s.session.userId;for(const it of x.items||[]){let need=Number(it.qty);const inv=s.inventory.filter(i=>i.productCode===it.code&&Number(i.qty)>0&&inventorySiteId(i,s)===x.sourceSiteId);for(const row of inv){if(need<=0)break;const take=Math.min(Number(row.qty),need);row.qty=Number(row.qty)-take;need-=take;}if(need>0)throw new Error(`Stock insuficiente para ${it.code}`);}s.inventory=s.inventory.filter(i=>Number(i.qty)>0);},`Traspaso ${t.id} enviado`);return;}
 if(t.status==='EN_TRANSITO'){await store.commit(s=>{const x=s.transfers.find(z=>z.id===t.id),loc=ensureReceivingLocation(s,x.destinationSiteId);for(const it of x.items||[]){let row=s.inventory.find(i=>i.productCode===it.code&&i.locationId===loc.id&&!i.palletId);if(!row){row={id:`INV-TRF-${Date.now()}-${Math.random().toString(36).slice(2,7)}`,productCode:it.code,locationId:loc.id,qty:0,palletId:null};s.inventory.push(row);}row.qty=Number(row.qty||0)+Number(it.qty||0);}x.status='RECIBIDA';x.receivedAt=new Date().toISOString();x.receivedBy=s.session.userId;const o=s.orders.find(q=>q.id===x.orderId);if(o){o.events=o.events||[];o.events.push({at:new Date().toISOString(),userId:s.session.userId,message:`Traspaso ${x.id} recibido en ${siteName(x.destinationSiteId)}`});if(o.status==='ESPERANDO_REPOSICION')o.status=o.assignedTo?'ASIGNADA':'ACEPTADA';}},`Traspaso ${t.id} recibido`);}
}
function transferHtml(o){const trs=(store.data.transfers||[]).filter(t=>t.orderId===o.id&&t.type==='REPOSICION_PEDIDO');if(!trs.length)return '';return `<section class="order-transfers"><h3>Traspasos para completar la orden</h3>${trs.map(t=>`<div class="history-row"><div class="hist-icon">⇄</div><div><b>${esc(t.id)} · ${esc(siteName(t.sourceSiteId))} → ${esc(siteName(t.destinationSiteId))}</b><small>${(t.items||[]).map(i=>`${esc(i.code)} · ${i.qty} un.`).join(' · ')}</small></div>${badge(t.status,t.status==='RECIBIDA'?'ok':t.status==='EN_TRANSITO'?'warn':'neutral')}${isManager()&&['SOLICITADA','EN_TRANSITO'].includes(t.status)?`<button class="secondary advance-transfer" data-transfer="${esc(t.id)}" type="button">${t.status==='SOLICITADA'?'Marcar en tránsito':'Recibir en bodega'}</button>`:''}</div>`).join('')}</section>`;}

function orderCard(o){const p=progress(o),issued=o.status==='EMITIDA';return `<button class="order-card" data-order="${esc(o.id)}" data-search="${esc(orderSearchText(o))}" data-date="${esc((o.closedAt||o.createdAt||'').slice(0,10))}" type="button"><div class="order-card-top"><div><span class="eyebrow">${esc(o.externalNumber||o.id)} · ${esc(orderTypeLabel(o.orderType))}</span><h3>${esc(siteName(o.sourceSiteId))} → ${esc(destinationName(o))}</h3>${issued?`<small class="issued-card-document">${esc(o.finalDocumentType||'Documento')} ${esc(o.finalDocumentNumber||'Sin número')}</small>`:''}</div>${badge(statusLabel(o.status),statusTone(o.status))}</div><div class="order-assignee"><span>Operador</span><b>${esc(userName(o.assignedTo))}</b></div><div class="progress-line"><div><span style="width:${p.pct}%"></span></div><b>${p.done} / ${p.total}</b><small>${p.pct}%</small></div><div class="order-card-foot"><small>${new Date(o.closedAt||o.createdAt).toLocaleString('es-CL')}</small><b>${issued?'Ver documento →':'Ver operación →'}</b></div></button>`;}
function orderDetail(o){const p=progress(o);const canWork=o.assignedTo===me()?.id||isManager(),missingUnits=(o.items||[]).reduce((sum,it)=>sum+Math.max(0,Number(it.qty||0)-Number(it.pickedQty||0)),0);const rows=(o.items||[]).map((it,idx)=>{const prod=store.data.products.find(x=>x.code===it.productCode),picked=Number(it.pickedQty||0),requested=Number(it.qty||0),missing=Math.max(0,requested-picked),done=picked>=requested,stock=stockStatus(it.productCode,o.sourceSiteId,store.data,o.id);return `<div class="pick-item ${done?'done':''}" data-item-search="${esc(itemSearchText(it))}"><div class="pick-status">${done?'✓':idx+1}</div><div class="pick-main"><button class="product-link" data-code="${esc(it.productCode)}" type="button"><b>${esc(it.productCode)} · ${esc(prod?.name||prod?.description||'Producto')}</b></button><div class="pick-readable-location"><span>UBICACIÓN</span><b>${esc(locationText(it.productCode,o.sourceSiteId))}</b></div><small><b>Stock:</b> físico ${stock.physical} · reservado ${stock.reserved} · disponible ${stock.available}</small><div class="order-alias-chips">${aliasChips(prod)}</div><div class="pick-location-actions"><a href="#/mapa3d?code=${encodeURIComponent(it.productCode)}&returnOrder=${encodeURIComponent(o.id)}">Ver mapa 3D</a><a href="#/buscar?code=${encodeURIComponent(it.productCode)}">Ver stock global</a></div>${['PENDIENTE_EMISION','ESPERANDO_REPOSICION'].includes(o.status)&&missing?`<small class="order-shortage">Faltante registrado: ${missing} un.</small>`:''}</div><div class="pick-qty"><small>Preparado</small><b>${picked} / ${requested}</b><small>Solicitado ${requested}</small></div></div>`;}).join('');
 const accept=isManager()&&o.status==='RECIBIDA'?`<div class="order-assign"><div><b>Orden pendiente de aceptación</b><small>Revísala antes de asignarla a un operario.</small></div><button id="accept-order" class="primary" type="button">Aceptar orden</button></div>`:'';
 const assign=isManager()&&['ACEPTADA','ASIGNADA','EN_PICKING'].includes(o.status)?`<div class="order-assign"><label>Asignar tarea<select id="order-operator"><option value="">Selecciona operario</option>${operators().map(u=>`<option value="${esc(u.id)}" ${u.id===o.assignedTo?'selected':''}>${esc(u.name)}</option>`).join('')}</select></label><button id="assign-order" class="secondary" type="button">Asignar</button></div>`:'';
 const scan=canWork&&['ASIGNADA','EN_PICKING'].includes(o.status)?`<section class="pick-scan"><div><span class="eyebrow">PICKING GUIADO</span><h3>Escanea o busca el producto que estás preparando</h3><p>Mientras escribes, la lista se filtra temporalmente y muestra cantidad solicitada y ubicación.</p></div><form id="pick-form"><div class="pick-search-wrap"><div class="entrada-con-camara"><input id="pick-code" autocomplete="off" placeholder="Empieza a escribir: 141026, popup 90…"><button id="pick-camera" class="scan-button" type="button">▣</button></div><div id="pick-suggestions" class="pick-suggestions" hidden></div></div><input id="pick-qty" type="number" min="1" step="1" value="1" inputmode="numeric"><button class="primary" type="submit">Confirmar</button></form><div id="pick-focus-guide" class="pick-focus-guide" hidden></div></section>`:'';
 const finish=canWork&&['ASIGNADA','EN_PICKING'].includes(o.status)?`<div class="order-final"><button id="finish-picking" class="primary" type="button">Culminar orden</button><small>Se enviará a emisión. Las cantidades no preparadas quedarán registradas como faltantes y todavía no se descontará stock.</small></div>`:'';
 const emission=isManager()&&['PENDIENTE_EMISION','PREPARADA'].includes(o.status)?`<section class="order-emission"><div><span class="eyebrow">DECISIÓN DEL ADMINISTRADOR</span><h3>${missingUnits?`Picking parcial · faltan ${missingUnits} un.`:'Picking completo'}</h3><p>Los datos se recuperaron de la orden original. Puedes corregirlos antes de emitir; nada se descuenta hasta confirmar.</p></div>${missingUnits?`<div class="order-admin-paths"><button id="wait-shortages" class="secondary" type="button">Esperar productos faltantes</button><small>Cuando llegue mercancía, reabre el picking y el operador la escanea dentro de esta misma orden.</small></div>`:''}<div class="order-inherited-data"><b>Datos heredados</b><span>${esc(orderTypeLabel(o.orderType))} · orden ${esc(o.externalNumber||o.id)} · ${esc(siteName(o.sourceSiteId))} → ${esc(destinationName(o))}</span>${o.recipient?`<small>${esc(o.recipient.taxId||'Sin identificación')} · ${esc(o.recipient.address||'Sin dirección')} · ${esc(o.recipient.contact||'Sin contacto')}</small>`:''}</div><div class="order-emission-grid"><label>Tipo de documento<select id="final-document-type"><option value="FACTURA" ${defaultDocumentType(o)==='FACTURA'?'selected':''}>Factura</option><option value="GUIA_DESPACHO" ${defaultDocumentType(o)==='GUIA_DESPACHO'?'selected':''}>Guía de despacho</option><option value="TRASPASO" ${defaultDocumentType(o)==='TRASPASO'?'selected':''}>Traspaso</option><option value="PEDIDO" ${defaultDocumentType(o)==='PEDIDO'?'selected':''}>Pedido</option><option value="OTRO" ${defaultDocumentType(o)==='OTRO'?'selected':''}>Otro</option></select></label><label>Número / referencia<input id="final-document-number" value="${esc(o.finalDocumentNumber||o.externalNumber||o.id)}" placeholder="Ej. FAC-1025 o TRF-58"></label><label>Recibido por / destinatario<input id="final-receiver" value="${esc(o.finalReceiver||(destinationName(o)==='Destinatario externo'?'':destinationName(o)))}" placeholder="Nombre, cliente o conductor"></label><label class="full">Observación final<input id="final-notes" value="${esc(o.finalNotes||o.notes||'')}" placeholder="Opcional"></label></div><div class="order-emission-actions"><button id="close-order-no-stock" class="ghost" type="button">Cerrar sin emitir</button><button id="emit-order" class="primary" type="button">${missingUnits?'Emitir lo preparado y cerrar':'Emitir y cerrar orden'}</button></div></section>`:'';
 const waiting=isManager()&&o.status==='ESPERANDO_REPOSICION'?`<section class="order-waiting"><span class="eyebrow">ESPERANDO REPOSICIÓN</span><h3>La orden conserva lo preparado y espera ${missingUnits} unidad(es)</h3><p>Recibe o traspasa el producto mediante los módulos normales. Cuando el stock ya esté disponible, reabre el picking para que el operador lo escanee.</p><div><a class="secondary" href="#/recepciones">Ir a Recepción</a><a class="secondary" href="#/transferencias">Ir a Despacho / Tránsito</a><button id="resume-picking" class="primary" type="button">Reabrir picking y continuar</button></div></section>`:'';
 const emitted=o.status==='EMITIDA'?`<section class="order-issued-summary"><div><span class="eyebrow">DOCUMENTO EMITIDO</span><h3>${esc(o.finalDocumentType||'Documento')} · ${esc(o.finalDocumentNumber||'Sin número')}</h3><small>${esc(o.finalReceiver||'Sin destinatario')} · ${o.closedAt?new Date(o.closedAt).toLocaleString('es-CL'):''}</small></div><button id="print-issued-document" class="primary" type="button">Ver / imprimir PDF</button></section>`:'';
 const closed=o.status==='CERRADA'&&o.closeReason==='SIN_EMISION'?`<section class="order-released-summary"><div><span class="eyebrow">ORDEN CERRADA SIN EMISIÓN</span><h3>Cantidades liberadas y disponibles</h3><small>La orden queda en el historial. Puedes crear una nueva solicitud con los mismos productos.</small></div><button id="reorder-closed-order" class="secondary" type="button">Volver a solicitar productos</button></section>`:'';
 const activity=`<details class="order-timeline order-collapsible"><summary><span><b>Actividad de la orden</b><small>${(o.events||[]).length} registro(s)</small></span><strong>Mostrar</strong></summary><div class="order-collapsible-content">${(o.events||[]).slice().reverse().map(e=>`<div><b>${esc(e.message)}</b><small>${esc(userName(e.userId))} · ${new Date(e.at).toLocaleString('es-CL')}</small></div>`).join('')}</div></details>`;
 return `<section class="panel order-detail" data-order-id="${esc(o.id)}"><div class="panel-head"><div><span class="eyebrow">ORDEN ${esc(o.externalNumber||o.id)} · ${esc(orderTypeLabel(o.orderType))}</span><h2>${esc(statusLabel(o.status))}</h2><small>${esc(siteName(o.sourceSiteId))} → ${esc(destinationName(o))} · Operador: ${esc(userName(o.assignedTo))}</small></div><button id="close-order" class="ghost" type="button">Cerrar vista</button></div><div class="order-progress-big"><div><span style="width:${p.pct}%"></span></div><b>${p.done} de ${p.total} productos · ${p.pct}%</b></div>${scan}${accept}${assign}<div class="pick-list">${rows||empty('Orden sin productos')}</div>${finish}${o.status==='EMITIDA'?'':availabilityHtml(o)}${transferHtml(o)}${emission}${waiting}${emitted}${closed}${activity}</section>`;
}
function validateOrderRows(rows){if(!rows.length)return {errors:['El Excel está vacío.'],items:[]};const headers=rows[0].map(normalizeHeader);const ci=headers.findIndex(h=>['CODIGO','SKU','CODIGO_PRODUCTO'].includes(h));const qi=headers.findIndex(h=>['CANTIDAD','CANT','QTY'].includes(h));if(ci<0||qi<0)return {errors:['El Excel debe contener las columnas CODIGO (o SKU) y CANTIDAD.'],items:[]};const errors=[];const map=new Map();rows.slice(1).forEach((r,n)=>{const raw=String(r[ci]??'').trim(),qty=Number(r[qi]);if(!raw&&!r[qi])return;const p=resolveProduct(raw);if(!p){errors.push(`Fila ${n+2}: código ${raw||'(vacío)'} no asociado a ningún producto.`);return;}if(!Number.isFinite(qty)||qty<=0){errors.push(`Fila ${n+2}: cantidad inválida para ${raw}.`);return;}const old=map.get(p.code)||{productCode:p.code,qty:0,pickedQty:0,inputCodes:[]};old.qty+=qty;old.inputCodes.push(raw);map.set(p.code,old);});return {errors,items:[...map.values()]};}
function previewHtml(){if(!preview)return '<div class="import-empty">Selecciona un Excel para validar la orden.</div>';return `${preview.errors.length?`<div class="import-errors"><b>Hay datos que debes corregir:</b>${preview.errors.map(e=>`<p>${esc(e)}</p>`).join('')}</div>`:`<div class="callout"><b>Orden lista</b><span>${preview.items.length} productos reconocidos en el catálogo maestro.</span></div>`}<div class="table-wrap"><table><thead><tr><th>Código maestro</th><th>Producto</th><th>Cantidad</th></tr></thead><tbody>${preview.items.map(i=>{const p=store.data.products.find(x=>x.code===i.productCode);return `<tr><td><b>${esc(i.productCode)}</b></td><td>${esc(p?.name||p?.description||'Producto')}</td><td>${i.qty}</td></tr>`;}).join('')}</tbody></table></div>`;}
function createDialog(){return `<dialog id="order-dialog" class="order-dialog-wide"><form id="order-form" class="dialog-card order-create-card"><div class="dialog-head"><div><span class="eyebrow">NUEVA ORDEN</span><h3>Cargar orden desde Excel</h3></div><button type="button" id="close-order-dialog" class="ghost">×</button></div><div class="form-grid"><label>Número de orden<input id="order-number" placeholder="Ej. 4500123"></label><label>Centro preparador<select id="order-source">${store.data.sites.filter(s=>s.active!==false&&siteCompanyId(s)===activeCompanyId()).map(s=>`<option value="${esc(s.id)}">${esc(s.name)}</option>`).join('')}</select></label><label>Centro solicitante / destino<select id="order-request"><option value="">Selecciona destino</option>${store.data.sites.filter(s=>s.active!==false&&siteCompanyId(s)===activeCompanyId()).map(s=>`<option value="${esc(s.id)}">${esc(s.name)}</option>`).join('')}</select></label><label>Archivo Excel<input id="order-file" type="file" accept=".xlsx,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet" required></label></div><small>Solo necesitas CODIGO/SKU y CANTIDAD. El WMS obtiene descripción y demás datos desde el catálogo existente.</small><div id="order-preview">${previewHtml()}</div><div class="dialog-actions"><button type="button" id="cancel-order" class="ghost">Cancelar</button><button id="save-order" class="primary" type="submit" disabled>Crear orden</button></div></form></dialog>`;}
function manualItemsHtml(){if(!manualItems.length)return '<div class="import-empty">Agrega el primer SKU y su cantidad.</div>';const source=document.querySelector('#manual-order-source')?.value||store.data.session?.activeSiteId||'REC';return `<div class="table-wrap"><table><thead><tr><th>SKU maestro</th><th>Producto y códigos asociados</th><th>Stock</th><th>Cantidad</th><th></th></tr></thead><tbody>${manualItems.map((i,index)=>{const p=store.data.products.find(x=>x.code===i.productCode),stock=stockStatus(i.productCode,source),global=totalCompanyStock(i.productCode);return `<tr><td><b>${esc(i.productCode)}</b></td><td><b>${esc(p?.name||p?.description||'Producto')}</b><div class="manual-alias-chips">${aliasChips(p)}</div></td><td><small>${esc(siteName(source))}</small><b class="manual-stock-number">${stock.physical} un.</b><small>Disponible ${stock.available} · Global ${global}</small></td><td><b>${Number(i.qty)}</b></td><td><button class="ghost remove-manual-item" data-index="${index}" type="button">Quitar</button></td></tr>`;}).join('')}</tbody></table></div>`;}
function manualDialog(){const allSites=store.data.sites.filter(s=>s.active!==false&&siteCompanyId(s)===activeCompanyId()),allowedIds=new Set((me()?.siteIds||[]).length?me().siteIds:[localStorage.getItem('serco_wms_active_site')||store.data.session?.activeSiteId||'REC']),sites=isGlobalManager()?allSites:allSites.filter(s=>allowedIds.has(s.id)),recipients=savedRecipients(),drafts=(store.data.settings?.orderDrafts||[]).filter(d=>d.createdBy===me()?.id);return `<dialog id="manual-order-dialog" class="order-dialog-wide"><form id="manual-order-form" class="dialog-card order-create-card"><div class="dialog-head"><div><span class="eyebrow">CARGA OPERATIVA</span><h3>Cargar orden manualmente</h3><small>Primero arma la orden, luego revísala y solamente al final confírmala.</small></div><button type="button" id="close-manual-order" class="ghost">×</button></div><section class="manual-draft-bar"><label>Borradores guardados<select id="manual-draft-select"><option value="">Nueva orden</option>${drafts.map(d=>`<option value="${esc(d.id)}">${esc(d.number||'Sin referencia')} · ${new Date(d.updatedAt).toLocaleString('es-CL')}</option>`).join('')}</select></label><button id="load-manual-draft" class="secondary" type="button">Cargar borrador</button></section><div id="manual-edit-step"><div class="form-grid"><label>Tipo de orden<select id="manual-order-type"><option value="PEDIDO_CLIENTE">Pedido de cliente</option><option value="TRASPASO_INTERNO">Traspaso interno</option><option value="FACTURA_DIRECTA">Factura directa</option><option value="GUIA_DESPACHO">Guía de despacho</option><option value="ORDEN_INTERNA">Orden interna</option><option value="OTRO">Otro</option></select></label><label>Número / referencia<input id="manual-order-number" placeholder="Se genera automáticamente si queda vacío"></label><label>${isGlobalManager()?'Centro preparador':'Centro preparador asignado'}<select id="manual-order-source" ${isGlobalManager()?'':'disabled'}>${sites.map(s=>`<option value="${esc(s.id)}">${esc(s.name)}</option>`).join('')}</select></label><label>Tipo de destino<select id="manual-destination-mode"><option value="INTERNAL">Centro / sucursal interna</option><option value="EXTERNAL">Cliente, persona u otro destino</option></select></label></div><section id="manual-internal-destination" class="manual-destination-panel"><label>Centro destino<select id="manual-order-request"><option value="">Selecciona centro destino</option>${allSites.map(s=>`<option value="${esc(s.id)}">${esc(s.name)}</option>`).join('')}</select></label><small>Para un traspaso, el centro destino debe ser diferente del preparador.</small></section><section id="manual-external-destination" class="manual-destination-panel" hidden><div class="manual-recipient-grid"><label>Destinatario guardado<select id="manual-saved-recipient"><option value="">Nuevo destinatario manual</option>${recipients.map(r=>`<option value="${esc(r.id)}">${esc(r.name)}${r.taxId?` · ${esc(r.taxId)}`:''}</option>`).join('')}</select></label><label>Tipo<select id="manual-recipient-type"><option value="CLIENTE">Cliente</option><option value="PERSONA">Persona</option><option value="PROVEEDOR">Proveedor</option><option value="OBRA">Obra / proyecto</option><option value="OTRO">Otro</option></select></label><label>Nombre o razón social<input id="manual-recipient-name" placeholder="Obligatorio"></label><label>RUT / identificación<input id="manual-recipient-taxid" placeholder="Opcional"></label><label>Dirección o lugar de entrega<input id="manual-recipient-address" placeholder="Casa, obra, sucursal externa…"></label><label>Contacto / teléfono<input id="manual-recipient-contact" placeholder="Opcional"></label></div><label class="manual-save-recipient"><input id="manual-save-recipient" type="checkbox"> Guardar este destinatario para próximas órdenes</label><small>Queda estructurado para vincularlo posteriormente con el identificador del cliente en Kame.</small></section><section class="manual-line-entry"><div><label>SKU, código o nombre del producto<div class="entrada-con-camara"><input id="manual-product-code" autocomplete="off" placeholder="Empieza a escribir: popup 90, 4140…"><button id="manual-product-camera" class="scan-button" type="button">▣</button></div></label><div id="manual-product-match" class="manual-product-match"></div><div id="manual-product-suggestions" class="manual-product-suggestions" hidden></div></div><label>Cantidad<input id="manual-product-qty" type="number" min="1" step="1" value="1" inputmode="numeric"></label><button id="add-manual-item" class="secondary" type="button">Agregar producto</button></section><div id="manual-items-preview">${manualItemsHtml()}</div><div class="dialog-actions"><button type="button" id="cancel-manual-order" class="ghost">Cancelar</button><button id="save-manual-draft" class="secondary" type="button">Guardar borrador</button><button id="review-manual-order" class="primary" type="button" disabled>Revisar orden</button></div></div><section id="manual-review-step" class="manual-review-step" hidden><span class="eyebrow">REVISIÓN ANTES DE GENERAR</span><h3>Confirma que la información esté correcta</h3><div id="manual-review-content"></div><div class="dialog-actions"><button id="back-manual-edit" class="ghost" type="button">← Seguir editando</button><button id="save-manual-order" class="primary" type="submit">Confirmar y generar orden</button></div></section></form></dialog>`;}
function newOrderRecord({number,source,request,orderType,items,recipient,origin}){const now=new Date().toISOString();return {id:`ORD-${Date.now()}`,externalNumber:number||`WMS-${Date.now()}`,source:origin||'MANUAL',orderType:orderType||'PEDIDO_CLIENTE',companyId:siteCompanyId(store.data.sites.find(z=>z.id===source),store.data),sourceSiteId:source,requestSiteId:request||null,recipient:recipient?structuredClone(recipient):null,status:'RECIBIDA',assignedTo:null,items:structuredClone(items),createdAt:now,createdBy:store.data.session.userId,events:[{at:now,userId:store.data.session.userId,message:`Orden creada por carga ${(origin||'MANUAL').toLowerCase()}`}]};}
async function acceptOrder(o){await store.commit(s=>{const x=s.orders.find(q=>q.id===o.id);x.status='ACEPTADA';x.acceptedAt=new Date().toISOString();x.acceptedBy=s.session.userId;x.events=x.events||[];x.events.push({at:new Date().toISOString(),userId:s.session.userId,message:'Orden aceptada por bodega'});},`Orden ${o.externalNumber||o.id} aceptada`);}
async function assignOrder(o,userId){if(!userId){toast('Selecciona un operario');return;}await store.commit(s=>{const x=s.orders.find(q=>q.id===o.id);x.assignedTo=userId;x.status='ASIGNADA';x.assignedAt=new Date().toISOString();x.events=x.events||[];x.events.push({at:new Date().toISOString(),userId:s.session.userId,message:`Orden asignada a ${userName(userId)}`});},`Orden ${o.externalNumber||o.id} asignada`);}
async function pick(o,raw,qty){const p=resolveOrderProduct(o,raw);if(!p){toast('Código no reconocido');return;}const item=o.items.find(i=>i.productCode===p.code);if(!item){toast('Ese producto no pertenece a esta orden');return;}const remaining=Number(item.qty)-Number(item.pickedQty||0);if(qty<1||qty>remaining){toast(`Cantidad pendiente: ${remaining}`);return;}const available=stockStatus(p.code,o.sourceSiteId,store.data,o.id).available;if(available<Number(item.pickedQty||0)+qty){toast(`Stock disponible para esta orden en ${siteName(o.sourceSiteId)}: ${Math.max(0,available-Number(item.pickedQty||0))}`);return;}await store.commit(s=>{const x=s.orders.find(q=>q.id===o.id);const it=x.items.find(i=>i.productCode===p.code);it.pickedQty=Number(it.pickedQty||0)+qty;it.lastScannedCode=String(raw).trim();x.status='EN_PICKING';x.pickingStartedAt=x.pickingStartedAt||new Date().toISOString();x.events=x.events||[];x.events.push({at:new Date().toISOString(),userId:s.session.userId,message:`${p.code}: ${it.pickedQty}/${it.qty} preparado`});if(x.items.every(i=>Number(i.pickedQty||0)>=Number(i.qty))&&!x.pickingReadyAt){x.pickingReadyAt=new Date().toISOString();x.events.push({at:new Date().toISOString(),userId:s.session.userId,message:'Todos los productos están preparados · listo para culminar'});}},`Picking ${o.externalNumber||o.id}: ${p.code}`);}
async function finishPicking(o){await store.commit(s=>{const x=s.orders.find(q=>q.id===o.id),now=new Date().toISOString();for(const it of x.items||[])it.shortageQty=Math.max(0,Number(it.qty||0)-Number(it.pickedQty||0));x.status='PENDIENTE_EMISION';x.pickingCompletedAt=now;x.pickingCompletedBy=s.session.userId;x.events=x.events||[];const missing=(x.items||[]).reduce((sum,it)=>sum+Number(it.shortageQty||0),0);x.events.push({at:now,userId:s.session.userId,message:missing?`Picking culminado con ${missing} unidad(es) faltante(s) · enviado a emisión`:'Picking culminado completo · enviado a emisión'});},`Picking culminado · orden ${o.externalNumber||o.id}`);}
async function waitForShortages(o){await store.commit(s=>{const x=s.orders.find(q=>q.id===o.id),now=new Date().toISOString();x.status='ESPERANDO_REPOSICION';x.waitingSince=now;x.events=x.events||[];x.events.push({at:now,userId:s.session.userId,message:'Administrador decidió esperar los productos faltantes'});},`Orden ${o.externalNumber||o.id} esperando reposición`);}
async function resumePicking(o){await store.commit(s=>{const x=s.orders.find(q=>q.id===o.id),now=new Date().toISOString();x.status='EN_PICKING';x.resumedAt=now;x.events=x.events||[];x.events.push({at:now,userId:s.session.userId,message:'Picking reabierto para escanear productos recibidos'});},`Picking reabierto · orden ${o.externalNumber||o.id}`);}
async function closeWithoutEmission(o){await store.commit(s=>{const x=s.orders.find(q=>q.id===o.id),now=new Date().toISOString();x.status='CERRADA';x.closedAt=now;x.closedBy=s.session.userId;x.closeReason='SIN_EMISION';x.events=x.events||[];x.events.push({at:now,userId:s.session.userId,message:'Orden cerrada sin documento ni descuento de stock'});},`Orden ${o.externalNumber||o.id} cerrada sin emisión`);}
async function reorderClosedOrder(o){const now=new Date().toISOString(),record={...structuredClone(o),id:`ORD-${Date.now()}`,externalNumber:`RE-${o.externalNumber||o.id}-${String(Date.now()).slice(-4)}`,status:'RECIBIDA',assignedTo:null,createdAt:now,createdBy:store.data.session.userId,acceptedAt:null,acceptedBy:null,assignedAt:null,pickingStartedAt:null,pickingCompletedAt:null,pickingCompletedBy:null,closedAt:null,closedBy:null,closeReason:null,finalDocumentType:null,finalDocumentNumber:null,finalReceiver:null,finalNotes:null,source:'REPOSICION_ORDEN_CERRADA',parentOrderId:o.id,items:(o.items||[]).map(it=>({...structuredClone(it),pickedQty:0,dispatchedQty:0,shortageQty:0,lastScannedCode:null})),events:[{at:now,userId:store.data.session.userId,message:`Nueva solicitud creada desde la orden cerrada ${o.externalNumber||o.id}`} ]};await store.commit(s=>{s.orders=s.orders||[];s.orders.unshift(record);},`Productos solicitados nuevamente desde ${o.externalNumber||o.id}`);}
async function emitOrder(o,{documentType,documentNumber,receiver,notes}){if(!documentType||!documentNumber)throw new Error('Selecciona el tipo e ingresa el número del documento.');const prepared=(o.items||[]).reduce((sum,it)=>sum+Number(it.pickedQty||0),0);if(prepared<1)throw new Error('No hay cantidades preparadas para emitir.');if(documentType==='TRASPASO'&&(!o.requestSiteId||o.requestSiteId===o.sourceSiteId))throw new Error('Un traspaso necesita un centro destino diferente al centro preparador.');for(const it of o.items||[]){const qty=Number(it.pickedQty||0);if(qty>0&&(stockBySite(it.productCode)[o.sourceSiteId]||0)<qty)throw new Error(`Stock insuficiente para emitir ${it.productCode}.`);}await store.commit(s=>{const x=s.orders.find(q=>q.id===o.id),now=new Date().toISOString();for(const it of x.items||[]){let need=Number(it.pickedQty||0);const inv=s.inventory.filter(i=>i.productCode===it.productCode&&Number(i.qty)>0).filter(i=>(s.locations.find(l=>l.id===i.locationId)?.siteId||'REC')===x.sourceSiteId);for(const row of inv){if(need<=0)break;const take=Math.min(Number(row.qty),need);row.qty=Number(row.qty)-take;need-=take;}if(need>0)throw new Error(`Stock insuficiente para ${it.productCode}`);it.dispatchedQty=Number(it.pickedQty||0);}s.inventory=s.inventory.filter(i=>Number(i.qty)>0);if(documentType==='TRASPASO'){s.transfers=s.transfers||[];s.transfers.unshift({id:`TRF-${Date.now()}`,type:'ORDEN_EMITIDA',orderId:x.id,sourceSiteId:x.sourceSiteId,destinationSiteId:x.requestSiteId,status:'EN_TRANSITO',createdAt:now,departedAt:now,createdBy:s.session.userId,dispatchedBy:s.session.userId,items:x.items.filter(it=>Number(it.pickedQty||0)>0).map(it=>({code:it.productCode,qty:Number(it.pickedQty||0)})),destinationName:siteName(x.requestSiteId)});}x.status='EMITIDA';x.finalDocumentType=documentType;x.finalDocumentNumber=documentNumber;x.finalReceiver=receiver||'';x.finalNotes=notes||'';x.closedAt=now;x.closedBy=s.session.userId;x.events=x.events||[];x.events.push({at:now,userId:s.session.userId,message:`${documentType} ${documentNumber} emitido · orden cerrada · ${prepared} unidad(es) descontadas`});},`Orden ${o.externalNumber||o.id} emitida como ${documentType} ${documentNumber}`);}
async function deliver(o){const driver=prompt('Nombre del conductor que retira la mercancía:')?.trim();if(!driver)return;for(const it of o.items||[]){if(Number(it.pickedQty||0)<Number(it.qty||0))throw new Error(`La orden aún no está completa para ${it.productCode}.`);const available=stockBySite(it.productCode)[o.sourceSiteId]||0;if(available<Number(it.qty)){throw new Error(`Stock insuficiente para ${it.productCode}. Disponible: ${available}`);}}await store.commit(s=>{const x=s.orders.find(q=>q.id===o.id);for(const it of x.items){let need=Number(it.qty);const inv=s.inventory.filter(i=>i.productCode===it.productCode&&Number(i.qty)>0).filter(i=>(s.locations.find(l=>l.id===i.locationId)?.siteId||'REC')===x.sourceSiteId);for(const row of inv){if(need<=0)break;const take=Math.min(Number(row.qty),need);row.qty=Number(row.qty)-take;need-=take;}if(need>0)throw new Error(`Stock insuficiente para ${it.productCode}`);}s.inventory=s.inventory.filter(i=>Number(i.qty)>0);for(const it of x.items)it.dispatchedQty=Number(it.qty||0);x.status='ENTREGADA_CONDUCTOR';x.driverName=driver;x.deliveredAt=new Date().toISOString();x.events=x.events||[];x.events.push({at:new Date().toISOString(),userId:s.session.userId,message:`Mercancía entregada al conductor ${driver}`});},`Orden ${o.externalNumber||o.id} entregada a conductor`);toast('Orden entregada al conductor');}
function wireDetail(root,o){document.querySelectorAll('.request-shortage').forEach(b=>b.onclick=async()=>{const sel=document.querySelector(`.shortage-site[data-code="${CSS.escape(b.dataset.code)}"]`);await requestShortage(o,b.dataset.code,Number(b.dataset.qty),sel?.value);renderOrders(root,o.id);});document.querySelectorAll('.advance-transfer').forEach(b=>b.onclick=async()=>{try{const t=store.data.transfers.find(x=>x.id===b.dataset.transfer);await advanceTransfer(t);renderOrders(root,o.id);}catch(e){toast(e.message,'warning');}});document.querySelectorAll('.order-collapsible').forEach(d=>d.addEventListener('toggle',()=>{const label=d.querySelector('summary>strong');if(label)label.textContent=d.open?'Ocultar':'Mostrar';}));document.querySelector('#accept-order')?.addEventListener('click',async()=>{await acceptOrder(o);renderOrders(root,o.id);});document.querySelector('#close-order').onclick=()=>document.querySelector('#order-detail-slot').innerHTML='';document.querySelectorAll('.product-link').forEach(b=>b.onclick=()=>location.hash=`#/productos?code=${encodeURIComponent(b.dataset.code)}`);document.querySelector('#assign-order')?.addEventListener('click',async()=>{await assignOrder(o,document.querySelector('#order-operator').value);renderOrders(root);});if(document.querySelector('#pick-form')){const input=document.querySelector('#pick-code'),suggestions=document.querySelector('#pick-suggestions'),guide=document.querySelector('#pick-focus-guide'),rows=[...document.querySelectorAll('.pick-item')];const paintSuggestions=()=>{const q=normalizedSearch(input.value);suggestions.innerHTML=pickSuggestionsHtml(o,input.value);suggestions.hidden=!q;guide.innerHTML=pickFocusHtml(o,input.value);guide.hidden=!q;rows.forEach(row=>{const match=!q||q.split(/\s+/).every(t=>row.dataset.itemSearch.includes(t));row.hidden=!match;row.classList.toggle('search-focus',Boolean(q&&match));});suggestions.querySelectorAll('.pick-suggestion-select').forEach(b=>b.onclick=()=>{input.value=b.dataset.code;paintSuggestions();suggestions.hidden=true;input.focus();});};enlazarBotonEscaner('pick-camera','pick-code',{titulo:'Escanear producto',ayuda:'Escanea cualquiera de sus códigos asociados',onDetectar:paintSuggestions});input.addEventListener('input',paintSuggestions);input.addEventListener('keydown',e=>{if(e.key==='Escape'){input.value='';paintSuggestions();suggestions.hidden=true;}});document.querySelector('#pick-form').onsubmit=async e=>{e.preventDefault();await pick(o,input.value.trim(),Number(document.querySelector('#pick-qty').value||1));renderOrders(root,o.id);};}document.querySelector('#print-issued-document')?.addEventListener('click',()=>showPrintableDocument(o));document.querySelector('#reorder-closed-order')?.addEventListener('click',async()=>{await reorderClosedOrder(o);toast('Productos solicitados nuevamente','success');renderOrders(root);});document.querySelector('#finish-picking')?.addEventListener('click',async()=>{if(!confirm('¿Culminar esta orden y enviarla a emisión? Las cantidades pendientes quedarán registradas como faltantes.'))return;try{await finishPicking(o);toast('Orden culminada y enviada a emisión','success');renderOrders(root,o.id);}catch(e){toast(e.message,'warning');}});document.querySelector('#wait-shortages')?.addEventListener('click',async()=>{await waitForShortages(o);toast('Orden en espera de productos faltantes','success');renderOrders(root,o.id);});document.querySelector('#resume-picking')?.addEventListener('click',async()=>{await resumePicking(o);toast('Picking reabierto; el operador puede continuar escaneando','success');renderOrders(root,o.id);});document.querySelector('#close-order-no-stock')?.addEventListener('click',async()=>{if(!confirm('¿Cerrar esta orden sin emitir documento y liberar las cantidades reservadas?'))return;await closeWithoutEmission(o);toast('Orden cerrada; las cantidades quedaron disponibles','success');renderOrders(root,o.id);});document.querySelector('#emit-order')?.addEventListener('click',async()=>{try{await emitOrder(o,{documentType:document.querySelector('#final-document-type').value,documentNumber:document.querySelector('#final-document-number').value.trim(),receiver:document.querySelector('#final-receiver').value.trim(),notes:document.querySelector('#final-notes').value.trim()});toast('Documento emitido y orden cerrada','success');renderOrders(root,o.id);}catch(e){toast(e.message,'warning');}});}
export function renderOrders(root,openId=null){
 if(liveTimer){clearInterval(liveTimer);liveTimer=null;}
 const routeParams=new URLSearchParams(location.hash.split('?')[1]||'');openId=openId||routeParams.get('openOrder');
 const title=isManager()?'Órdenes y Picking':'Mis tareas',orders=visibleOrders().slice().sort((a,b)=>String(b.closedAt||b.createdAt).localeCompare(String(a.closedAt||a.createdAt))),operatorDone=new Set(['PENDIENTE_EMISION','PREPARADA','EMITIDA','CERRADA','ENTREGADA_CONDUCTOR']),issued=orders.filter(o=>isManager()?['EMITIDA','CERRADA','ENTREGADA_CONDUCTOR'].includes(o.status):operatorDone.has(o.status)),active=orders.filter(o=>isManager()?!['EMITIDA','CERRADA','ENTREGADA_CONDUCTOR'].includes(o.status):!operatorDone.has(o.status));
 const managerActions=isManager()?'<div class="order-create-actions"><button id="new-manual-order" class="primary" type="button">+ Cargar orden manualmente</button><button id="new-order" class="secondary" type="button">Importar orden Excel</button></div>':'';
 const archive=isManager()?`<section class="order-archive-tools"><div><span class="eyebrow">CONSULTA GLOBAL</span><h3>Buscar órdenes y documentos</h3><small>Número de factura, orden, fecha, destinatario, operador, emisor, producto o código asociado.</small></div><div class="order-archive-filters"><input id="order-global-search" autocomplete="off" placeholder="Escribe y filtra al instante…"><select id="order-state-filter"><option value="ALL">Todos los estados</option><option value="ACTIVE">Solo operación activa</option><option value="ISSUED">Solo emitidos</option></select><input id="order-date-filter" type="date"><button id="clear-order-filters" class="ghost" type="button">Limpiar</button></div><b id="order-filter-count">${orders.length} resultado(s)</b></section>`:'';
 const activeSection=`<section class="order-section" data-order-section="ACTIVE"><div class="order-section-head"><div><span class="eyebrow">OPERACIÓN ACTIVA</span><h3>Órdenes en proceso</h3></div><b>${active.length}</b></div><div class="orders-grid">${active.length?active.map(orderCard).join(''):empty('Sin órdenes activas','No hay tareas pendientes en este momento.')}</div></section>`;
 const issuedSection=isManager()?`<section class="order-section issued-orders" data-order-section="ISSUED"><div class="order-section-head"><div><span class="eyebrow">ARCHIVO DOCUMENTAL</span><h3>Emitidos y cerrados</h3><small>Cada documento puede abrirse por separado e imprimirse o guardarse como PDF.</small></div><b>${issued.length}</b></div><div class="orders-grid">${issued.length?issued.map(orderCard).join(''):empty('Sin documentos emitidos','Los documentos aparecerán aquí después de emitir y cerrar.')}</div></section>`:`<details class="operator-history order-collapsible"><summary><span><b>Órdenes ya realizadas</b><small>${issued.length} orden(es) separadas de las tareas activas</small></span><strong>Mostrar</strong></summary><div class="order-collapsible-content orders-grid">${issued.length?issued.map(orderCard).join(''):empty('Sin tareas realizadas','Tus órdenes culminadas aparecerán aquí.')}</div></details>`;
 const body=`<div class="page-intro"><div><span class="eyebrow">OPERACIÓN</span><h2>${esc(title)}</h2><p>${isManager()?'Crea órdenes, asígnalas, controla el picking y emite el documento final.':'Aquí aparecen únicamente las órdenes que te fueron asignadas.'}</p></div>${managerActions}</div><button id="orders-sync-notice" class="orders-sync-notice" type="button" hidden>Hay cambios nuevos · actualizar vista</button>${archive}${activeSection}${issuedSection}<div id="order-detail-slot"></div>${isManager()?createDialog()+manualDialog():''}`;
 root.innerHTML=shell(title,body,'ordenes');wireShell();
 document.querySelectorAll('.order-card').forEach(b=>b.onclick=()=>{const o=store.data.orders.find(x=>x.id===b.dataset.order),slot=document.querySelector('#order-detail-slot');slot.innerHTML=orderDetail(o);slot.scrollIntoView({behavior:'smooth',block:'start'});wireDetail(root,o);});
 if(openId){const o=store.data.orders.find(x=>x.id===openId);if(o){const slot=document.querySelector('#order-detail-slot');slot.innerHTML=orderDetail(o);wireDetail(root,o);requestAnimationFrame(()=>slot.scrollIntoView({behavior:'auto',block:'start'}));}}
 if(isManager()){wireOrderCreation(root);wireOrderArchive();}
 document.querySelectorAll('.operator-history').forEach(d=>d.addEventListener('toggle',()=>{const label=d.querySelector('summary>strong');if(label)label.textContent=d.open?'Ocultar':'Mostrar';}));
 document.querySelector('#orders-sync-notice')?.addEventListener('click',()=>renderOrders(root,document.querySelector('.order-detail')?.dataset.orderId||null));
 liveTimer=setInterval(async()=>{if(!location.hash.startsWith('#/ordenes')){clearInterval(liveTimer);return;}try{const before=store.data.meta?.revision;await store.reload({emit:false});if(store.data.meta?.revision===before)return;const busy=document.querySelector('dialog[open]')||document.querySelector('.order-detail')||['INPUT','SELECT','TEXTAREA'].includes(document.activeElement?.tagName);if(busy){const notice=document.querySelector('#orders-sync-notice');if(notice)notice.hidden=false;return;}renderOrders(root);}catch{}},10000);
}

function wireOrderArchive(){const search=document.querySelector('#order-global-search'),state=document.querySelector('#order-state-filter'),date=document.querySelector('#order-date-filter'),count=document.querySelector('#order-filter-count');if(!search)return;const apply=()=>{const q=search.value.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().trim();let shown=0;document.querySelectorAll('.order-section').forEach(section=>{const sectionAllowed=state.value==='ALL'||section.dataset.orderSection===state.value;let sectionShown=0;section.querySelectorAll('.order-card').forEach(card=>{const ok=sectionAllowed&&(!q||card.dataset.search.includes(q))&&(!date.value||card.dataset.date===date.value);card.hidden=!ok;if(ok){shown++;sectionShown++;}});section.hidden=!sectionAllowed||(!sectionShown&&Boolean(q||date.value));});count.textContent=`${shown} resultado(s)`;};search.addEventListener('input',apply);state.addEventListener('change',apply);date.addEventListener('input',apply);document.querySelector('#clear-order-filters').onclick=()=>{search.value='';state.value='ALL';date.value='';apply();search.focus();};}

function wireOrderCreation(root){
 const excelDialog=document.querySelector('#order-dialog'),manualDialogEl=document.querySelector('#manual-order-dialog');
 excelDialog.addEventListener('cancel',e=>e.preventDefault());manualDialogEl.addEventListener('cancel',e=>e.preventDefault());
 document.querySelector('#new-order').onclick=()=>{preview=null;document.querySelector('#order-preview').innerHTML=previewHtml();document.querySelector('#save-order').disabled=true;excelDialog.showModal();};
 document.querySelector('#close-order-dialog').onclick=()=>excelDialog.close();document.querySelector('#cancel-order').onclick=()=>excelDialog.close();
 document.querySelector('#order-file').onchange=async e=>{try{preview=validateOrderRows(await parseXlsx(e.target.files?.[0]));document.querySelector('#order-preview').innerHTML=previewHtml();document.querySelector('#save-order').disabled=preview.errors.length>0||preview.items.length===0;}catch(err){preview={errors:[err.message],items:[]};document.querySelector('#order-preview').innerHTML=previewHtml();}};
 document.querySelector('#order-form').onsubmit=async e=>{e.preventDefault();if(!preview||preview.errors.length)return;const source=document.querySelector('#order-source').value,request=document.querySelector('#order-request').value;if(!source||!request){toast('Selecciona centro preparador y destino');return;}const number=document.querySelector('#order-number').value.trim()||`WMS-${Date.now()}`,record=newOrderRecord({number,source,request,orderType:'PEDIDO_CLIENTE',items:preview.items,origin:'EXCEL'});await store.commit(s=>{s.orders=s.orders||[];s.orders.unshift(record);},`Orden ${number} importada`);excelDialog.close();toast('Orden creada');renderOrders(root,record.id);};
 const refreshManual=()=>{document.querySelector('#manual-items-preview').innerHTML=manualItemsHtml();document.querySelector('#review-manual-order').disabled=manualItems.length===0;document.querySelectorAll('.remove-manual-item').forEach(b=>b.onclick=()=>{manualItems.splice(Number(b.dataset.index),1);refreshManual();});};
 const toggleDestination=()=>{const external=document.querySelector('#manual-destination-mode').value==='EXTERNAL';document.querySelector('#manual-internal-destination').hidden=external;document.querySelector('#manual-external-destination').hidden=!external;};
 const showEditStep=()=>{document.querySelector('#manual-edit-step').hidden=false;document.querySelector('#manual-review-step').hidden=true;};
 document.querySelector('#new-manual-order').onclick=()=>{manualItems=[];document.querySelector('#manual-order-form').reset();document.querySelector('#manual-product-match').innerHTML='';document.querySelector('#manual-product-suggestions').hidden=true;showEditStep();toggleDestination();refreshManual();manualDialogEl.showModal();};
 document.querySelector('#close-manual-order').onclick=()=>manualDialogEl.close();document.querySelector('#cancel-manual-order').onclick=()=>manualDialogEl.close();
 document.querySelector('#manual-destination-mode').onchange=toggleDestination;
 document.querySelector('#manual-order-type').onchange=e=>{if(e.target.value==='TRASPASO_INTERNO'){document.querySelector('#manual-destination-mode').value='INTERNAL';toggleDestination();}};
 document.querySelector('#manual-order-source').onchange=()=>{refreshManual();showMatch();};
 document.querySelector('#manual-saved-recipient').onchange=e=>{const r=savedRecipients().find(x=>x.id===e.target.value);if(!r)return;document.querySelector('#manual-recipient-type').value=r.type||'CLIENTE';document.querySelector('#manual-recipient-name').value=r.name||'';document.querySelector('#manual-recipient-taxid').value=r.taxId||'';document.querySelector('#manual-recipient-address').value=r.address||'';document.querySelector('#manual-recipient-contact').value=r.contact||'';};
 const draftPayload=()=>({id:document.querySelector('#manual-draft-select').value||`DRAFT-${Date.now()}`,number:document.querySelector('#manual-order-number').value.trim(),orderType:document.querySelector('#manual-order-type').value,source:document.querySelector('#manual-order-source').value,mode:document.querySelector('#manual-destination-mode').value,request:document.querySelector('#manual-order-request').value,savedRecipient:document.querySelector('#manual-saved-recipient').value,recipientType:document.querySelector('#manual-recipient-type').value,recipientName:document.querySelector('#manual-recipient-name').value.trim(),recipientTaxId:document.querySelector('#manual-recipient-taxid').value.trim(),recipientAddress:document.querySelector('#manual-recipient-address').value.trim(),recipientContact:document.querySelector('#manual-recipient-contact').value.trim(),saveRecipient:document.querySelector('#manual-save-recipient').checked,items:structuredClone(manualItems),createdBy:me()?.id,updatedAt:new Date().toISOString()});
 const loadDraft=d=>{document.querySelector('#manual-order-number').value=d.number||'';document.querySelector('#manual-order-type').value=d.orderType||'PEDIDO_CLIENTE';document.querySelector('#manual-order-source').value=d.source||document.querySelector('#manual-order-source').value;document.querySelector('#manual-destination-mode').value=d.mode||'INTERNAL';document.querySelector('#manual-order-request').value=d.request||'';document.querySelector('#manual-saved-recipient').value=d.savedRecipient||'';document.querySelector('#manual-recipient-type').value=d.recipientType||'CLIENTE';document.querySelector('#manual-recipient-name').value=d.recipientName||'';document.querySelector('#manual-recipient-taxid').value=d.recipientTaxId||'';document.querySelector('#manual-recipient-address').value=d.recipientAddress||'';document.querySelector('#manual-recipient-contact').value=d.recipientContact||'';document.querySelector('#manual-save-recipient').checked=Boolean(d.saveRecipient);manualItems=structuredClone(d.items||[]);toggleDestination();showEditStep();refreshManual();};
 document.querySelector('#load-manual-draft').onclick=()=>{const id=document.querySelector('#manual-draft-select').value,d=(store.data.settings?.orderDrafts||[]).find(x=>x.id===id&&x.createdBy===me()?.id);if(!d){toast('Selecciona un borrador guardado','warning');return;}loadDraft(d);toast('Borrador cargado','success');};
 document.querySelector('#save-manual-draft').onclick=async()=>{const draft=draftPayload();await store.commit(s=>{s.settings=s.settings||{};s.settings.orderDrafts=s.settings.orderDrafts||[];const index=s.settings.orderDrafts.findIndex(x=>x.id===draft.id);if(index>=0)s.settings.orderDrafts[index]=draft;else s.settings.orderDrafts.unshift(draft);},`Borrador de orden ${draft.number||draft.id} guardado`);const select=document.querySelector('#manual-draft-select');let option=[...select.options].find(o=>o.value===draft.id);if(!option){option=document.createElement('option');option.value=draft.id;select.append(option);}option.textContent=`${draft.number||'Sin referencia'} · guardado ahora`;select.value=draft.id;toast('Borrador guardado; puedes seguir editando o continuar después','success');};
 document.querySelector('#review-manual-order').onclick=()=>{if(!manualItems.length){toast('Agrega al menos un producto','warning');return;}const d=draftPayload();if(d.mode==='INTERNAL'&&!d.request){toast('Selecciona el centro destino','warning');return;}if(d.orderType==='TRASPASO_INTERNO'&&d.request===d.source){toast('El destino del traspaso debe ser diferente','warning');return;}if(d.mode==='EXTERNAL'&&!d.recipientName){toast('Ingresa el destinatario','warning');return;}document.querySelector('#manual-review-content').innerHTML=`<div class="manual-review-summary"><div><small>TIPO / REFERENCIA</small><b>${esc(orderTypeLabel(d.orderType))} · ${esc(d.number||'Se generará automáticamente')}</b></div><div><small>ORIGEN / DESTINO</small><b>${esc(siteName(d.source))} → ${esc(d.mode==='INTERNAL'?siteName(d.request):d.recipientName)}</b></div><div><small>PRODUCTOS</small><b>${d.items.length} SKU · ${d.items.reduce((sum,i)=>sum+Number(i.qty||0),0)} unidades</b></div></div>${manualItemsHtml()}`;document.querySelector('#manual-edit-step').hidden=true;document.querySelector('#manual-review-step').hidden=false;};
 document.querySelector('#back-manual-edit').onclick=showEditStep;
 const showMatch=()=>{const input=document.querySelector('#manual-product-code'),raw=input.value.trim(),source=document.querySelector('#manual-order-source').value,exact=resolveProduct(raw),matches=productSuggestions(raw,source),slot=document.querySelector('#manual-product-match'),list=document.querySelector('#manual-product-suggestions');if(!raw){slot.innerHTML='';list.hidden=true;return;}if(exact){const stock=stockStatus(exact.code,source),global=totalCompanyStock(exact.code);slot.innerHTML=`<div class="manual-product-selected"><div><b>${esc(exact.code)} · ${esc(exact.name||exact.description||'Producto')}</b><div class="manual-alias-chips">${aliasChips(exact)}</div></div><div><small>${esc(siteName(source))}</small><strong>${stock.physical} un.</strong><small>Disponible ${stock.available} · Global ${global}</small></div></div>`;list.hidden=true;return;}slot.innerHTML=matches.length?`<small>${matches.length} coincidencia${matches.length===1?'':'s'} · selecciona una</small>`:'<span>Sin coincidencias por código, nombre o descripción.</span>';list.innerHTML=matches.map(p=>{const stock=stockStatus(p.code,source),global=totalCompanyStock(p.code);return `<button type="button" data-code="${esc(p.code)}"><div><b>${esc(p.code)} · ${esc(p.name||p.description||'Producto')}</b><div class="manual-alias-chips">${aliasChips(p)}</div></div><span><strong>${stock.physical} un.</strong><small>${esc(siteName(source))} · Disp. ${stock.available} · Global ${global}</small></span></button>`;}).join('');list.hidden=!matches.length;list.querySelectorAll('button').forEach(b=>b.onclick=()=>{input.value=b.dataset.code;list.hidden=true;showMatch();input.focus();});};
 document.querySelector('#manual-product-code').addEventListener('input',showMatch);document.querySelector('#manual-product-code').addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();document.querySelector('#add-manual-item').click();}});enlazarBotonEscaner('manual-product-camera','manual-product-code',{titulo:'Escanear producto para la orden',ayuda:'Puedes usar cualquier código asociado',onDetectar:showMatch});
 document.querySelector('#add-manual-item').onclick=()=>{const raw=document.querySelector('#manual-product-code').value.trim(),qty=Number(document.querySelector('#manual-product-qty').value),p=resolveProduct(raw);if(!p){toast('Selecciona una coincidencia válida antes de agregar','warning');return;}if(!Number.isInteger(qty)||qty<1){toast('Ingresa una cantidad válida','warning');return;}const existing=manualItems.find(i=>i.productCode===p.code);if(existing){existing.qty=Number(existing.qty)+qty;if(!existing.inputCodes.includes(raw))existing.inputCodes.push(raw);}else manualItems.push({productCode:p.code,qty,pickedQty:0,inputCodes:[raw]});document.querySelector('#manual-product-code').value='';document.querySelector('#manual-product-qty').value='1';document.querySelector('#manual-product-match').innerHTML='';document.querySelector('#manual-product-suggestions').hidden=true;refreshManual();document.querySelector('#manual-product-code').focus();};
 document.querySelector('#manual-order-form').onsubmit=async e=>{e.preventDefault();if(document.querySelector('#manual-review-step').hidden){toast('Primero revisa la orden antes de generarla','warning');return;}const orderType=document.querySelector('#manual-order-type').value,source=document.querySelector('#manual-order-source').value,mode=document.querySelector('#manual-destination-mode').value,request=mode==='INTERNAL'?document.querySelector('#manual-order-request').value:'',selectedRecipient=document.querySelector('#manual-saved-recipient').value,draftId=document.querySelector('#manual-draft-select').value;if(!manualItems.length){toast('Agrega al menos un producto','warning');return;}if(mode==='INTERNAL'&&!request){toast('Selecciona el centro destino','warning');return;}if(orderType==='TRASPASO_INTERNO'&&(mode!=='INTERNAL'||request===source)){toast('Un traspaso interno necesita un centro destino diferente','warning');return;}let recipient=null;if(mode==='EXTERNAL'){const name=document.querySelector('#manual-recipient-name').value.trim();if(!name){toast('Ingresa el nombre del destinatario externo','warning');return;}const saved=savedRecipients().find(r=>r.id===selectedRecipient);recipient={id:saved?.id||`DEST-${Date.now()}`,source:saved?.source||'MANUAL',kameId:saved?.kameId||null,type:document.querySelector('#manual-recipient-type').value,name,taxId:document.querySelector('#manual-recipient-taxid').value.trim(),address:document.querySelector('#manual-recipient-address').value.trim(),contact:document.querySelector('#manual-recipient-contact').value.trim()};}const number=document.querySelector('#manual-order-number').value.trim()||`WMS-${Date.now()}`,record=newOrderRecord({number,source,request,orderType,items:manualItems,recipient,origin:'MANUAL'}),saveRecipient=recipient&&document.querySelector('#manual-save-recipient').checked&&!selectedRecipient;await store.commit(s=>{s.orders=s.orders||[];s.orders.unshift(record);if(draftId&&s.settings?.orderDrafts)s.settings.orderDrafts=s.settings.orderDrafts.filter(d=>d.id!==draftId);if(saveRecipient){s.settings=s.settings||{};s.settings.orderRecipients=s.settings.orderRecipients||[];s.settings.orderRecipients.push({...recipient,companyId:record.companyId,active:true,createdAt:new Date().toISOString()});}},`Orden manual ${number} creada`);manualDialogEl.close();toast('Orden manual generada','success');renderOrders(root,record.id);};
}
